style.css:
/* Fundo geral */
body {
background-color: #ffe6f0 !important;
color: #5a3e4d !important;
}

/* Caixas / cards */
div, section, main {
background-color: #fff0f6 !important;
border-radius: 12px !important;
}

/* Botões */
button {
background-color: #ffb6d9 !important;
color: white !important;
border: none !important;
border-radius: 10px !important;
}

button:hover {
background-color: #ff9ecf !important;
}

/* Links */
a {
color: #ff66a3 !important;
}

/* Barra de rolagem (opcional, mas fica lindo) */
::-webkit-scrollbar {
width: 10px;
}

::-webkit-scrollbar-thumb {
background: #ffb6d9;
border-radius: 10px;
}

/* Inputs (caixinhas de texto) */
input, textarea {
background-color: #fff5fa !important;
border: 1px solid #ffcce6 !important;
border-radius: 8px !important;
}
